"""DESIGN-TIME solver/conditioning check (stdlib only) -- NOT the experiment.

Purpose: choose the linear-solver backend for the IFT solve  H u = grad  and define the
observable diagnostics for the design's failure modes.
H = A + lam I with A = Xs^T Xs (PSD), so eigenvalues of H = eig(A) + lam.
Jacobi eigendecomposition gives exact kappa for moderate d (no numpy available here).
"""
import math
import random


def jacobi_eig(A, iters=200, tol=1e-14):
    n = len(A)
    a = [row[:] for row in A]
    for _ in range(iters):
        off = max((abs(a[i][j]), i, j) for i in range(n) for j in range(i + 1, n))
        if off[0] < tol:
            break
        _, p, q = off
        if abs(a[p][q]) < 1e-300:
            break
        theta = 0.5 * math.atan2(2 * a[p][q], a[p][p] - a[q][q])
        c, s = math.cos(theta), math.sin(theta)
        for k in range(n):
            akp, akq = a[k][p], a[k][q]
            a[k][p] = c * akp - s * akq
            a[k][q] = s * akp + c * akq
        for k in range(n):
            apk, aqk = a[p][k], a[q][k]
            a[p][k] = c * apk - s * aqk
            a[q][k] = s * apk + c * aqk
    return sorted(a[i][i] for i in range(n))


def mv(A, v):
    n, m = len(A), len(v)
    out = [0.0] * n
    for i in range(n):
        s = 0.0
        row = A[i]
        for j in range(m):
            s += row[j] * v[j]
        out[i] = s
    return out


def dot(a, b):
    return sum(x * y for x, y in zip(a, b))


def nrm(v):
    return math.sqrt(dot(v, v))


def neumann(H, b, terms, damp=None):
    """Truncated von Neumann series: u = sum_k (I - damp H)^k damp b  (explicit unrolling
    of the inverse -> memory/time grows with `terms`, like unrolled differentiation)."""
    L = max(jacobi_eig(H)[-1], 1e-12)
    eta = damp or (2.0 / (L + 1e-6))
    T = [eta * x for x in b]
    u = T[:]
    for k in range(terms - 1):
        T = [x - eta * y for x, y in zip(T, mv(H, T))]
        u = [a + b_ for a, b_ in zip(u, T)]
    return u


def cg(H, b, maxit, tol=1e-8):
    u = [0.0] * len(b)
    r = b[:]
    p = r[:]
    rs = dot(r, r)
    b0 = math.sqrt(rs) or 1.0
    for k in range(maxit):
        ph = mv(H, p)
        den = dot(p, ph)
        if den <= 0:
            return u, k + 1, math.sqrt(rs) / b0, False
        al = rs / den
        u = [x + al * z for x, z in zip(u, p)]
        r = [x - al * z for x, z in zip(r, ph)]
        rs_new = dot(r, r)
        if math.sqrt(rs_new) / b0 < tol:
            return u, k + 1, math.sqrt(rs_new) / b0, True
        p = [x + (rs_new / rs) * z for x, z in zip(r, p)]
        rs = rs_new
    return u, maxit, math.sqrt(rs) / b0, False


def psd(d, cond, rng):
    """A = V diag(eig) V^T style construction, cheap version: diagonal + low-rank noise."""
    ev = [cond ** (1.0 - i / max(1, d - 1)) for i in range(d)]
    Q = [[rng.gauss(0, 1) for _ in range(d)] for _ in range(d)]
    # orthogonalize (Gram-Schmidt) to make a real rotation
    for i in range(d):
        v = Q[i][:]
        for j in range(i):
            q = Q[j]
            v = [x - dot(v, q) * z for x, z in zip(v, q)]
        nv = nrm(v) or 1.0
        Q[i] = [x / nv for x in v]
    A = [[0.0] * d for _ in range(d)]
    for k in range(d):
        qk = Q[k]
        for i in range(d):
            for j in range(d):
                A[i][j] += ev[k] * qk[i] * qk[j]
    return A


def main():
    rng = random.Random(7)
    print("== F. solver backend choice vs dimension/conditioning (H = A + lam I) ==")
    print("   metric: rel error vs exact solve, and iterations needed (CG vs truncated Neumann)")
    for d in (16, 64):
        for cond in (10.0, 1e4):
            A = psd(d, cond, rng)
            for lam in (1.0, 1e-2):
                H = [[A[i][j] + (lam if i == j else 0.0) for j in range(d)] for i in range(d)]
                ev = jacobi_eig(H)
                lo, hi = ev[0], ev[-1]
                kappa = hi / max(lo, 1e-300)
                b = [rng.gauss(0, 1) for _ in range(d)]
                u_ref, _ = cg(H, b, 5000, 1e-13)
                u_cg, it_cg, r_cg, ok = cg(H, b, 200, 1e-8)
                errs = []
                for T in (1, 5, 10, 200):
                    u_n = neumann(H, b, T, damp=2.0 / (hi + lo))
                    e = nrm([x - y for x, y in zip(u_n, u_ref)]) / max(1e-30, nrm(u_ref))
                    errs.append(f"T={T}:{e:.1e}")
                print(f"  d={d:<3d} condA={cond:<8g} lam={lam:<5g} kappa(H)={kappa:<10.2e} "
                      f"CG: it={it_cg:<4d} res={r_cg:.1e} ok={ok} | Neumann " + " ".join(errs))

    print("== G. damping requirement for the Neumann/von-Neumann series ==")
    d, cond, lam = 32, 1e4, 1e-2
    A = psd(d, cond, rng)
    H = [[A[i][j] + (lam if i == j else 0.0) for j in range(d)] for i in range(d)]
    ev = jacobi_eig(H)
    lo, hi = ev[0], ev[-1]
    b = [rng.gauss(0, 1) for _ in range(d)]
    u_ref, _ = cg(H, b, 5000, 1e-13)
    print(f"  eig(H) in [{lo:.3e}, {hi:.3e}]  kappa={hi/lo:.2e}")
    for mult in (0.5, 1.0, 2.0):
        eta = mult * 2.0 / (hi + lo)          # optimal damping = 2/(hi+lo)
        u = neumann(H, b, 50, damp=eta)
        rho = max(abs(1 - eta * hi), abs(1 - eta * lo))
        print(f"  damp=mult*2/(hi+lo), mult={mult:<4g} rho(I-dampH)={rho:.4f} "
              f"rel_err(T=50)={nrm([x-y for x,y in zip(u,u_ref)])/nrm(u_ref):.2e}")

    print("== H. dual-variable norm ||u|| as the instability diagnostic (lam -> 0) ==")
    A = psd(32, 1e4, rng)
    b = [rng.gauss(0, 1) for _ in range(32)]
    for lam in (1.0, 1e-2, 1e-4, 1e-6, 1e-9):
        H = [[A[i][j] + (lam if i == j else 0.0) for j in range(32)] for i in range(32)]
        u, it, res, ok = cg(H, b, 500, 1e-8)
        print(f"  lam={lam:<8g} ||H^-1 b||={nrm(u):<12.3e} CG_it={it:<4d} res={res:.1e} CG_ok={ok}")


main()
