          for j in range(d):\n                A[i][j] += ev[k] * qk[i] * qk[j]\n    return A\n\n\ndef main():\n    rng = random.Random(7)\n    print(\"== F. solver backend choice vs dimension/conditioning (H = A + lam I) ==\")\n    print(\"   metric: rel error vs exact solve, and iterations needed (CG vs truncated Neumann)\")\n    for d in (16, 64):\n        for cond in (10.0, 1e4):\n            A = psd(d, cond, rng)\n            for lam in (1.0, 1e-2):\n                H = [[A[i][j] + (lam if i == j else 0.0) for j in range(d)] for i in range(d)]\n                ev = jacobi_eig(H)\n                lo, hi = ev[0], ev[-1]\n                kappa = hi / max(lo, 1e-300)\n                b = [rng.gauss(0, 1) for _ in range(d)]\n                u_ref, _ = cg(H, b, 5000, 1e-13)\n                u_cg, it_cg, r_cg, ok = cg(H, b, 200, 1e-8)\n                errs = []\n                for T in (1, 5, 10, 200):\n                    u_n = neumann(H, b, T, damp=2.0 / (hi + lo))\n                    e = nrm([x - y for x, y in zip(u_n, u_ref)]) / max(1e-30, nrm(u_ref))\n                    errs.append(f\"T={T}:{e:.1e}\")\n                print(f\"  d={d:<3d} condA={cond:<8g} lam={lam:<5g} kappa(H)={kappa:<10.2e} \"\n                      f\"CG: it={it_cg:<4d} res={r_cg:.1e} ok={ok} | Neumann \" + \" \".join(errs))\n\n    print(\"== G. damping requirement for the Neumann/von-Neumann series ==\")\n    d, cond, lam = 32, 1e4, 1e-2\n    A = psd(d, cond, rng)\n    H = [[A[i][j] + (lam if i == j else 0.0) for j in range(d)] for i in range(d)]\n    ev = jacobi_eig(H)\n    lo, hi = ev[0], ev[-1]\n    b = [rng.gauss(0, 1) for _ in range(d)]\n    u_ref, _ = cg(H, b, 5000, 1e-13)\n    print(f\"  eig(H) in [{lo:.3e}, {hi:.3e}]  kappa={hi/lo:.2e}\")\n    for mult in (0.5, 1.0, 2.0):\n        eta = mult * 2.0 / (hi + lo)          # optimal damping = 2/(hi+lo)\n        u = neumann(H, b, 50, damp=eta)\n        rho = max(abs(1 - eta * hi), abs(1 - eta * lo))\n        print(f\"  damp=mult*2/(hi+lo)