def _require_torch():
    import torch  # noqa: F401  (unavailable here by design)
    return torch


def functional_call(module, params, args=(), kwargs=None):
    """Forward pass with params supplied as a (meta) tensor tree -- never module buffers
    mutation.  Buffers/BN running stats are deliberately out of scope (see README S5)."""
    torch = _require_torch()
    if BACKEND == "torchopt":                                    # [VERIFY]
        import torchopt
        return torchopt.func.functional_call(module, params, args, kwargs or {})
    return torch.func.functional_call(module, params, args, kwargs or {})


def grad_params(fn, params, *a, **k):
    torch = _require_torch()
    if BACKEND == "torchopt":                                    # [VERIFY]
        import torchopt
        return torchopt.func.grad(fn, argnums=0)(*a, params=params, **k)
    return torch.func.grad(fn, argnums=0)(params, *a, **k)


def hvp(fn, params, v, *a, **k):
    """Hessian-vector product by double composition (jvp . grad).  This is the ONLY
    second-order primitive the IFT path needs -- no dense Hessian, keeps memory O(P)."""
    torch = _require_torch()
    g = torch.func.grad(fn, argnums=0)
    _, hv = torch.func.jvp(g, (params, v), (v, torch.zeros_like(params) if False else v))
    return hv


def jvp_params(fn, params, v, *a, **k):
    torch = _require_torch()
    return torch.func.jvp(fn, (params, v), (v,))


def cg_solve(matvec, rhs, max_iters, tol):
    """Matrix-free CG for the IFT system H u = rhs.  PRIMARY solve backend.
    Returns the iteration/residual diagnostics the design's failure-mode table needs."""
    dots = lambda x, y: sum((xi * yi).flatten().sum() for xi, yi in zip(_flat(x), _flat(y)))
    x = _zeros_like(rhs)
    r = rhs
    p = r
    rs = dots(r, r)
    b0 = rs.sqrt() if hasattr(rs, "sqrt") else rs ** 0.5
    for it in range(max_iters):
        ph = matvec(p)
        den = dots(p, ph)
        if den <= 0:                      # H not PD -> stop and report (failure mode 2)
            return x, it + 1, rs.sqrt(), False
        alpha = rs / den
        x, r = _axpy(x, alpha, p), _axpy(r, -alpha, ph)
        rs_new = dots(r, r)
        if float(rs_new) <= (tol * float(b0)) ** 2:
            return x, it + 1, rs_new.sqrt(), True
        p = _axpy(r, rs_new / rs, p)
        rs = rs_new
    return x, max_iters, rs.sqrt(), False


def neumann_apply(matvec, rhs, order, damp):
    """Truncated von Neumann series  sum_{k<order} (I - damp*H)^k damp*rhs  (ablation).
    NOTE (design-time check G): convergence needs damp < 2/lambda_max(H); over-damping
    diverges catastrophically.  `damp` must come from a power-iteration estimate."""
    terms, x = damp * rhs, damp * rhs
    for _ in range(order - 1):
        terms = damp * rhs - damp * matvec(terms) if False else _axpy(damp * rhs, -damp, matvec(terms))
        x = _axpy(x, 1.0, terms)
    return x


def power_iterate_lambda_max(matvec, x0, iters=100):
    """Estimate lambda_max(H) to set Neumann damping / report kappa proxy."""
    v = x0
    lam = None
    for _ in range(iters):
        w = matvec(v)
        lam = _dot(v, w)
        v = _scale(w, 1.0 / (_norm(w) + 1e-30))
    return lam


def implicit_meta_grad_closure(grad_fn, optim, solve=(50, 1e-8), perturbation=None):
    """HIGH-LEVEL TorchOpt path (the actual subject of the question).  [VERIFY]

    Documented shape (to confirm against TorchOpt docs/source):
        closure = torchopt.diff.implicit_diff.grad_closure(
            grad_fn=grad_fn,            # fn(params, meta_params) -> inner loss
            optim=optim,                # torchopt.meta.* optimizer, learnable meta params
            perturbation=perturbation,  # None -> exact IFT solve; Tensor -> perturbation approx
            solve=solve)                # (max_iters, tol) for the linear solve
        loss, meta_params = closure(inner_params, aux_params)
        g_inner, g_meta = grad_fn(inner_params, meta_params)   # -> IFT meta-gradient
    If the installed version differs, use `local_implicit_grad` in core.py, which
    implements the same IFT math with the primitives above.
    """
    if BACKEND != "torchopt":
        raise RuntimeError("torch backend: use core.local_implicit_grad instead")
    import torchopt                                              # [VERIFY]
    return torchopt.diff.implicit_diff.grad_closure(
        grad_fn=grad_fn, optim=optim, perturbation=perturbation, solve=solve)


# ---------------------------------------------------------------- small tree helpers
def _flat(tree):
    from torch.utils._pytree import tree_flatten      # [VERIFY] or torchopt.tree
    leaves, _ = tree_flatten(tree)
    return leaves


def _zeros_like(tree):
    return _tree_map(lambda t: torch_zeros(t), tree)


def torch_zeros(t):
    import torch
    return torch.zeros_like(t)


def _tree_map(f, tree):
    from torch.utils._pytree import tree_map          # [VERIFY]
    return tree_map(f, tree)


def _dot(a, b):
    return sum((x * y).sum() for x, y in zip(_flat(a), _flat(b)))


def _norm(v):
    return _dot(v, v) ** 0.5


def _scale(v, s):
    return _tree_map(lambda t: s * t, v)


def _axpy(a, s, b):
    return _tree_map(lambda x, y: x + s * y, a, b)
