"""Backend-agnostic IFT core (design-only skeleton, torch-dependent at runtime only).

Math (iMAML-style, inner problem solved to a FIXED POINT, not unrolled)
-----------------------------------------------------------------------
  f(theta, phi, lam) = 0.5||Xs theta - ys||^2 + 0.5*lam*||theta - phi||^2   (generalised:
                       f = L_support(theta) + 0.5*lam*||theta - phi||^2)
  stationarity map   g(theta, phi, lam) = d f / d theta = 0  defines theta*(phi, lam)
  H  = dg/dtheta     = Hess_theta L_support(theta*) + lam I        (SPD for lam > 0)
  u  = H^{-1} dL/dtheta|theta*                                     (matrix-free CG solve)
  dL/dphi =  lam * u
  dL/dlam = -u^T (theta* - phi)
For a vector meta-parameter (per-layer step sizes alpha in the MAML++-lite extension)
the same identity applies blockwise: dL/dalpha = -J_alpha^T u with J_alpha = dg/dalpha,
which the implementation obtains with jvp (forward) + vjp (backward) -- never by
forming H.  All identities above are numerically validated in design_check_ift.py.
"""
import adapter as A


# ------------------------------------------------------------------ inner problem
def inner_objective(model, xs, ys, phi, lam):
    """Regularized-valuated inner loss; the lambda term is what makes theta*(phi,lam)
    a well-posed fixed point (prerequisite for the IFT, unlike K-step unrolled MAML)."""
    def f(theta):
        pred = A.functional_call(model, theta, (xs,))
        data = 0.5 * ((pred - ys) ** 2).mean()
        pen = 0.5 * lam * _sqdist(theta, phi)
        return data + pen
    return f


def inner_solve(model, xs, ys, phi, lam, eta, max_steps, tol):
    """Solve to a fixed point with a TorchOpt (or plain) functional optimizer.
    [VERIFY] torchopt.init/torchopt.update; the loop is written so that
    torchopt.diff.implicit_diff.custom_root_find can replace it unchanged."""
    f = inner_objective(model, xs, ys, phi, lam)
    theta = A._tree_map(lambda t: t.clone(), phi)
    g = A.grad_params(f, theta)
    hist = []
    for k in range(max_steps):
        theta = A._axpy(theta, -eta, g)
        g = A.grad_params(f, theta)
        r = A._norm(g)
        hist.append(float(r))
        if float(r) < tol:                          # <-- fixed-point reached: IFT valid
            return theta, float(r), k + 1, hist
    return theta, float(A._norm(g)), max_steps, hist


# ------------------------------------------------------------------ IFT meta-grad
def hvp_of_inner_grad(model, xs, ys, phi, lam, theta):
    """matvec(v) = H v = d/deps [ grad f(theta + eps v) ] at eps=0."""
    f = inner_objective(model, xs, ys, phi, lam)
    return lambda v: A.hvp(f, theta, v)


def local_implicit_grad(model, xs, ys, xq, yq, phi, lam, theta_star,
                        solve=("cg", 50, 1e-8)):
    """Exact IFT meta-gradient with the diagnostics the failure-mode table consumes."""
    f = inner_objective(model, xs, ys, phi, lam)
    Lq = lambda t: 0.5 * ((A.functional_call(model, t, (xq,)) - yq) ** 2).mean()
    grad_meta = A.grad_params(Lq, theta_star)
    matvec = hvp_of_inner_grad(model, xs, ys, phi, lam, theta_star)
    mode, max_iters, tol = solve
    if mode == "cg":
        u, it, res, ok = A.cg_solve(matvec, grad_meta, max_iters, tol)
    elif mode == "neumann":                          # ablation; needs damp < 2/lambda_max
        damp = 1.0 / (A.power_iterate_lambda_max(matvec, grad_meta) + 1e-12)
        u = A.neumann_apply(matvec, grad_meta, max_iters, damp)
        it, res, ok = max_iters, float("nan"), None
    elif mode == "perturb":                          # ablation: first-order surrogate
        u = grad_meta                                # H^{-1} -> identity
        it, res, ok = 0, float("nan"), False
    else:
        raise ValueError(mode)
    dphi = A._scale(u, lam)
    dlam = -float(A._dot(u, _sub(theta_star, phi)))
    return dict(dphi=dphi, dlam=dlam, u=u,
                diag=dict(cg_iters=it, cg_resid=float(res), cg_converged=ok,
                          u_norm=float(A._norm(u)),
                          inner_resid=float(A._norm(A.grad_params(f, theta_star)))))


def unrolled_grad(model, xs, ys, xq, yq, phi, lam, eta, k):
    """GROUND TRUTH: differentiate through k explicit inner steps (memory O(k)).
    Only feasible for small k/models -- used for the agreement controls."""
    theta = phi
    for _ in range(k):
        theta = A._axpy(theta, -eta, A.grad_params(
            inner_objective(model, xs, ys, phi, lam), theta))
    return A.grad_params(lambda t: 0.5 * ((A.functional_call(model, t, (xq,)) - yq) ** 2).mean(), theta)


def ridge_analytic(Xs, ys, Xq, yq, lam, phi):
    """Closed-form control (task #3): exact theta*, exact hyper-gradients, no solver.
    dL/dphi = lam (X'X+lam I)^-1 grad ;  dL/dlam = -u^T (theta*-phi)."""
    raise NotImplementedError("implemented in design_check_ift.py; port to torch verbatim")


# ------------------------------------------------------------------ helpers
def _sqdist(a, b):
    return A._dot(_sub(a, b), _sub(a, b))


def _sub(a, b):
    return A._tree_map(lambda x, y: x - y, a, b)
